SELECT a.discharge_location, a.hospice, a.deathtime IS NOT NULL AS in_hospital_death, AVG(a.los) AS average_los, MEDIAN(a.los) AS median_los, SUM(CASE WHEN a.los <= 5 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(a.los), 0) AS proportion_los_less_than_5 FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 79 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2014 AND 2018 AND p.anchor_year_group IN ('74-78', '79-83', '84-88') GROUP BY a.discharge_location, a.hospice, in_hospital_death ORDER BY average_los NULLS LAST, median_los NULLS LAST, proportion_los_less_than_5 NULLS LAST;